import React from 'react';
import { Box, Button } from '@mui/material';

export type MsmeRegistrationSuccessActionsProps = {
  profileComplete: boolean;
  pendingBillingPlanId: string | null;
  onFinishMyCompany: () => void;
  onGoToDashboard: () => void;
  onRegisterAnother: () => void;
};

/**
 * Success footer actions. Exactly one contained primary:
 * - Profile complete → Finish My company (or billing-aware label) to /operations.
 * - Profile incomplete → checklist owns the contained CTA; Finish stays outlined secondary.
 */
export const MsmeRegistrationSuccessActions: React.FC<MsmeRegistrationSuccessActionsProps> = ({
  profileComplete,
  pendingBillingPlanId,
  onFinishMyCompany,
  onGoToDashboard,
  onRegisterAnother,
}) => {
  const finishLabel = pendingBillingPlanId
    ? 'Finish My company, then review your plan'
    : 'Finish My company';

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 1.5,
      }}
    >
      {profileComplete ? (
        <Button
          variant="contained"
          color={pendingBillingPlanId ? 'secondary' : 'primary'}
          onClick={onFinishMyCompany}
          sx={{ minWidth: { xs: '100%', sm: 280 }, maxWidth: 420 }}
        >
          {finishLabel}
        </Button>
      ) : null}
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          gap: 1,
          flexWrap: 'wrap',
          width: '100%',
        }}
      >
        {!profileComplete ? (
          <Button
            variant="outlined"
            color={pendingBillingPlanId ? 'secondary' : 'primary'}
            onClick={onFinishMyCompany}
            sx={{ minWidth: { xs: '100%', sm: 220 } }}
          >
            {finishLabel}
          </Button>
        ) : null}
        <Button
          variant="outlined"
          onClick={onGoToDashboard}
          sx={{ minWidth: { xs: '100%', sm: 180 } }}
        >
          Go to dashboard
        </Button>
        <Button
          variant="text"
          onClick={onRegisterAnother}
          sx={{ minWidth: { xs: '100%', sm: 160 } }}
        >
          Register Another
        </Button>
      </Box>
    </Box>
  );
};
