import React, { useMemo } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
} from '@mui/material';
import { CheckCircleOutline, RadioButtonUnchecked } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { getSignupGoalOption, type SignupGoalId } from '../../constants/signupGoals';
import { deriveOnboardingSteps, type OnboardingStep } from '../../utils/sustainabilityUx';
import { MSME_SIMPLIFIED_SECTION_TITLE } from '../../constants/msmeSimplifiedUi';

export interface PostRegistrationChecklistProps {
  companyName: string;
  pathway: 'msme' | 'enterprise';
  signupGoal?: SignupGoalId | null;
  /** When true, profile step shows as complete (e.g. GST captured during registration). */
  profileComplete?: boolean;
  /**
   * When true, omit the contained checklist CTA (parent already shows the primary action).
   * List step navigation stays available.
   */
  hidePrimaryCta?: boolean;
}

const ENTERPRISE_DEFAULT_STEPS: OnboardingStep[] = [
  {
    id: 'enterprise-facilities',
    label: 'Confirm facilities and Scope 3 materiality',
    description: 'Map sites and material categories for enterprise reporting.',
    path: '/enterprise',
    complete: false,
  },
  {
    id: 'enterprise-compliance',
    label: 'Complete evidence-backed compliance workflow',
    description: 'Close mandatory checklist items before filing-ready exports.',
    path: '/compliance',
    complete: false,
  },
  {
    id: 'enterprise-data',
    label: 'Connect accounting data or upload documents',
    description: 'Import books or upload bills for activity-backed inventory.',
    path: '/data',
    complete: false,
  },
  {
    id: 'enterprise-inventory',
    label: 'Run enterprise carbon inventory',
    description: 'Calculate organizational footprint with assurance gates.',
    path: '/carbon-footprint?section=start-assessment',
    complete: false,
  },
];

/** My company stays required before bills, footprint, and billing. */
const MSME_EARLY_OPS_STEP: OnboardingStep = {
  id: 'plant-picture',
  label: 'Finish My company',
  description: 'Energy, manufacturing units, direct emissions, value chain, and boundaries.',
  path: '/operations',
  complete: false,
  estimatedMinutes: 15,
};

export const PostRegistrationChecklist: React.FC<PostRegistrationChecklistProps> = ({
  companyName,
  pathway,
  signupGoal,
  profileComplete = false,
  hidePrimaryCta = false,
}) => {
  const navigate = useNavigate();
  const goal = getSignupGoalOption(signupGoal ?? null);
  const msmeProgress = useMemo(
    () =>
      deriveOnboardingSteps({
        hasProfile: profileComplete,
        hasDocuments: false,
        hasAssessment: false,
      }),
    [profileComplete]
  );
  const steps: OnboardingStep[] =
    pathway === 'enterprise'
      ? ENTERPRISE_DEFAULT_STEPS
      : (() => {
          const base = [...msmeProgress.steps];
          const profileIdx = base.findIndex((step) => step.id === 'profile');
          const insertAt = profileIdx >= 0 ? profileIdx + 1 : 0;
          base.splice(insertAt, 0, {
            ...MSME_EARLY_OPS_STEP,
            // Soft-complete when profile already done so primary CTA stays on bills.
            complete: false,
          });
          return base;
        })();
  const nextRequiredStep =
    pathway === 'msme'
      ? msmeProgress.steps.find((step) => !step.complete) ?? msmeProgress.steps[0]
      : steps.find((step) => !step.complete) ?? steps[0];

  return (
    <Card variant="outlined" sx={{ maxWidth: 640, mx: 'auto', mb: 3, textAlign: 'left' }}>
      <CardContent>
        <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
          {MSME_SIMPLIFIED_SECTION_TITLE} for {companyName}
        </Typography>
        {goal ? (
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
            Goal: <strong>{goal.label}</strong> — {goal.nextStepHint}
          </Typography>
        ) : null}
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, lineHeight: 1.55 }}>
          {pathway === 'msme'
            ? 'Finish My company before bills, footprint, or your signup goal. Those pages stay locked until energy, units, emissions, and boundaries are saved.'
            : 'Work through facilities, evidence, and inventory in order.'}
        </Typography>
        <List dense disablePadding>
          {steps.map((step) => (
            <ListItem key={step.id} disablePadding sx={{ py: 0.25 }}>
              <ListItemButton
                onClick={() => navigate(step.path.replace(/#.*$/, '') || step.path)}
                sx={{ borderRadius: 1 }}
              >
                <ListItemIcon sx={{ minWidth: 32 }}>
                  {step.complete ? (
                    <CheckCircleOutline color="success" fontSize="small" />
                  ) : (
                    <RadioButtonUnchecked color="disabled" fontSize="small" />
                  )}
                </ListItemIcon>
                <ListItemText
                  primary={step.label}
                  secondary={step.description}
                  primaryTypographyProps={{
                    variant: 'body2',
                    fontWeight: step.id === nextRequiredStep?.id || step.id === 'plant-picture' ? 600 : 500,
                  }}
                  secondaryTypographyProps={{ variant: 'caption' }}
                />
              </ListItemButton>
            </ListItem>
          ))}
        </List>

        {pathway === 'msme' && nextRequiredStep && !hidePrimaryCta ? (
          <Box sx={{ mt: 1.5, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
            <Button
              variant="contained"
              size="small"
              onClick={() => navigate(profileComplete ? '/operations' : nextRequiredStep.path)}
            >
              {profileComplete
                ? 'Finish My company'
                : `Complete company profile (~${nextRequiredStep.estimatedMinutes ?? 5} min)`}
            </Button>
          </Box>
        ) : null}
        <Box sx={{ mt: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Estimated time to first report: {pathway === 'enterprise' ? '2–4 hours' : '1–2 hours'} with
            documents ready.
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );
};
